// SIMULADOR: mantiene el estado en flow.estado y produce en msg.payload el
// MISMO contrato que consume el dashboard. En producción este nodo NO se usa;
// el dato real entra por la zona B (MQTT/NATS in) directo al publicador.
//
// Regla clave: el llenado de la bola es peso/peso_producto. El PESO_PRODUCTO
// viene de la ORDEN (campo pesoProducto) y es el 100% de las 3 bolas. Por eso
// el peso simulado crece de 0 a peso_producto y reinicia (nunca lo rebasa).
//
// El SETPOINT y la COLUMNA son datos del PLC: solo se muestran debajo de la
// bola y NO afectan el llenado. Los botones Subir/Bajar los editan (simulando
// el cambio desde Node-RED/PLC), pero no tocan el peso ni el tope de la bola.
//
// Los LEDS (paro/limpieza/ciclo) son POR VALVULADORA: cada bola tiene su propio
// objeto leds. Los botones led:* alternan el LED en las 3 a la vez (o en una
// sola si msg.payload trae el índice 0/1/2).

// Orden de ejemplo (solo para mostrar; no está conectada a nada real).
const ORDEN = {
    docNum: 955086,
    itemCode: 'PESP',
    itemName: 'COT. Pulido Espejo Blanco Pegaduro 10 kg',
    pesoProducto: 10, // <- tope de las bolas (100%)
    noLotes: 10
};

const SETPOINT_INI = 20; // setpoint inicial del PLC (kg) - solo se muestra
const COLUMNA_INI = 5;   // columna inicial del PLC (kg) - solo se muestra
const PASO = 1;          // cuánto cambia setpoint/columna por click

function acota(v, min, max) { return Math.max(min, Math.min(max, v)); }

// Estado persistente entre mensajes.
let e = flow.get('estado');
if (!e) {
    e = {
        machine_code: 'envasadora-1',
        of: String(ORDEN.docNum),
        item_code: ORDEN.itemCode,
        item_name: ORDEN.itemName,
        peso_producto: ORDEN.pesoProducto,
        lote_actual: 1,
        lotes_totales: ORDEN.noLotes,
        // Cada valvuladora tiene SUS PROPIOS leds (del PLC): paro/limpieza/ciclo.
        // Son por valvuladora, no de la máquina. Solo visuales.
        valvuladoras: [
            { peso: 0, setpoint: SETPOINT_INI, columna: COLUMNA_INI, leds: { paro: false, limpieza: false, ciclo: false }, bultos: 0, registros: [] },
            { peso: 0, setpoint: SETPOINT_INI, columna: COLUMNA_INI, leds: { paro: false, limpieza: false, ciclo: false }, bultos: 0, registros: [] },
            { peso: 0, setpoint: SETPOINT_INI, columna: COLUMNA_INI, leds: { paro: false, limpieza: false, ciclo: false }, bultos: 0, registros: [] }
        ]
    };
}
// Asegura que cada valvuladora tenga leds, contador de bultos y tabla (por si
// el estado viene de una versión anterior del flow).
e.valvuladoras.forEach(v => {
    if (!v.leds) v.leds = { paro: false, limpieza: false, ciclo: false };
    if (typeof v.bultos !== 'number') v.bultos = 0;
    if (!Array.isArray(v.registros)) v.registros = [];
});

// Máximo de bultos que se guardan para la tabla (el dashboard muestra los que caben).
const MAX_REGISTROS = 20;

// 'editando' define a qué valor del PLC afectan Subir/Bajar (setpoint/columna).
let editando = flow.get('editando') || 'setpoint';

// Tope de llenado: el peso_producto de la orden (mismo para las 3 bolas).
const tope = e.peso_producto > 0 ? e.peso_producto : 0;

switch (msg.topic) {
    case 'init':
        // Reinicia pesos, contador de bultos y tabla (la orden y el lote se quedan).
        e.valvuladoras.forEach(v => { v.peso = 0; v.bultos = 0; v.registros = []; });
        break;

    case 'sim':
        // Crece hacia el peso_producto (100% de la bola) y reinicia al llegar.
        // Se ACOTA al tope, así la bola nunca se rebasa.
        e.valvuladoras.forEach(v => {
            if (tope <= 0) { v.peso = 0; return; }
            if (v.peso >= tope) {
                // Bulto terminado: sube el contador y se agrega a la tabla
                // (al inicio = el más nuevo). El peso final simula una pequeña
                // variación alrededor del peso del producto.
                v.bultos += 1;
                v.registros.unshift({
                    id: String(v.bultos),
                    peso: Math.round((tope + (Math.random() - 0.5) * 0.1) * 100) / 100,
                    fecha: new Date().toISOString()
                });
                if (v.registros.length > MAX_REGISTROS) v.registros.length = MAX_REGISTROS;
                v.peso = 0; // reinicia el ciclo de llenado
            } else {
                const inc = Math.max(0.3, tope / 15) + Math.random() * (tope / 30);
                v.peso = acota(v.peso + inc, 0, tope);
            }
            v.peso = Math.round(v.peso * 10) / 10; // 1 decimal
        });
        break;

    case 'subir':
        // Solo edita el valor del PLC seleccionado; no toca peso ni tope.
        e.valvuladoras.forEach(v => {
            v[editando] = acota((v[editando] || 0) + PASO, 0, 9999);
        });
        break;

    case 'bajar':
        e.valvuladoras.forEach(v => {
            v[editando] = acota((v[editando] || 0) - PASO, 0, 9999);
        });
        break;

    case 'toggle':
        editando = (editando === 'setpoint') ? 'columna' : 'setpoint';
        flow.set('editando', editando);
        break;

    case 'led:paro':
    case 'led:limpieza':
    case 'led:ciclo': {
        // Qué LED: paro | limpieza | ciclo.
        const cual = msg.topic.split(':')[1];
        // A qué valvuladora: si msg.payload es un número (0,1,2) solo esa; si
        // no, alterna en las 3 a la vez (práctico para probar). El PLC real
        // mandará la señal por valvuladora de forma independiente.
        const idx = (typeof msg.payload === 'number') ? msg.payload : null;
        if (idx !== null && e.valvuladoras[idx]) {
            e.valvuladoras[idx].leds[cual] = !e.valvuladoras[idx].leds[cual];
        } else {
            e.valvuladoras.forEach(v => { v.leds[cual] = !v.leds[cual]; });
        }
        break;
    }
}

flow.set('estado', e);
node.status({ fill: 'blue', shape: 'dot', text: 'editando: ' + editando });

// Salida: el contrato exacto que consume el dashboard.
msg.payload = e;
return msg;

// Convierte el dato real (MQTT/NATS) al contrato del dashboard. Ajusta este
// mapeo según cómo llegue tu fuente. Si tu fuente YA manda el contrato exacto,
// deja el passthrough de abajo y borra el resto.
//
// Contrato esperado por el dashboard:
//   { machine_code, of, item_code, item_name, lote_actual, lotes_totales,
//     valvuladoras: [ { peso, setpoint, columna } x3 ] }

let d = msg.payload;
if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { return null; } }
if (!d || typeof d !== 'object') { return null; }

// --- Passthrough: la fuente ya manda el contrato ---
// (Comenta este bloque y usa el mapeo de abajo si tu fuente es distinta.)
if (Array.isArray(d.valvuladoras)) {
    msg.payload = d;
    return msg;
}

// --- Ejemplo de mapeo (adáptalo a tu fuente real) ---
// peso_producto es el tope de las bolas y viene de la orden (pesoProducto).
// setpoint y columna son del PLC (solo se muestran).
// msg.payload = {
//     machine_code: d.machine_code || 'envasadora-1',
//     of: String(d.docNum || ''),
//     item_code: d.itemCode || '',
//     item_name: d.itemName || '',
//     peso_producto: Number(d.pesoProducto) || 0,
//     lote_actual: d.loteActual || 1,
//     lotes_totales: d.noLotes || 0,
//     valvuladoras: (d.valvulas || []).map(x => ({
//         peso: Number(x.peso) || 0,
//         setpoint: Number(x.setpoint) || 0,
//         columna: Number(x.columna) || 0
//     }))
// };
// return msg;

return null;

// Punto ÚNICO de publicación: aquí llega el contrato ya armado (venga del
// simulador o de la entrada real). Fija el subject por machine_code y valida
// mínimamente antes de mandar.
const e = msg.payload;
if (!e || !Array.isArray(e.valvuladoras)) {
    node.warn('payload sin valvuladoras, no se publica');
    return null;
}

const code = e.machine_code || 'envasadora-1';
msg.topic = 'papid.envasadora.' + code; // si el nodo NATS usa msg.topic
return msg;
